{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>{{BUSINESS_NAME}} — Aromatic Intensives & Personalized Plans</title>
  <meta name="description" content="A modern aromatherapy practice offering focused sessions, custom blends, and home ritual guidance that may support calm, clarity, and focus." />
  <link rel="stylesheet" href="assets/css/styles.css">
</head>
<body class="asym-masonry">
  <header class="site-header">
    <div class="wrap">
      <a class="brand" href="/">{{BUSINESS_NAME}}</a>
      <nav class="main-nav">
        <a href="/services.html">Offerings</a>
        <a href="/blends.html">Botanical Blends</a>
        <a href="/shop.html">Apothecary</a>
        <a href="/pricing.html">Plans</a>
        <a href="/about.html">About</a>
        <a href="/book.html" class="cta">{{PRIMARY_CTA_LABEL}}</a>
        <a href="/contact.html">Connect</a>
      </nav>
    </div>
  </header>

  <main>
    <!-- HERO (first) -->
    <section class="hero" id="hero">
      <div class="wrap">
        <div class="hero-inner">
          <div class="hero-copy">
            <h1>{{TAGLINE}}</h1>
            <p class="subtitle">Guided aromatic sessions, personalized ritual plans, and hand-mixed blends that may support your daily rhythm. Practical. Gentle. Tailored.</p>
            <p class="meta">Phone: <a href="tel:{{PHONE}}">{{PHONE}}</a> • <a href="mailto:{{EMAIL}}">{{EMAIL}}</a> • Serving {{CITY}}, {{STATE}}</p>
            <p><a class="btn primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a> <a class="btn ghost" href="/book.html">Schedule a consultation</a></p>
          </div>
          <div class="hero-art">
            <svg class="pattern" viewBox="0 0 200 200" xmlns="http://www.w3.org/2000/svg" aria-hidden="true">
              <defs>
                <pattern id="p" patternUnits="userSpaceOnUse" width="40" height="40">
                  <rect width="40" height="40" fill="#f7faf6" />
                  <path d="M0 20 Q10 5 20 20 T40 20" fill="none" stroke="#dfece5" stroke-width="1.5" />
                </pattern>
              </defs>
              <rect width="100%" height="100%" fill="url(#p)" />
            </svg>
          </div>
        </div>
      </div>
    </section>

    <!-- FRAMEWORK (second) -->
    <section class="framework" id="framework">
      <div class="wrap">
        <h2>How this practice works</h2>
        <p class="lede">We blend sensory skill with practical steps: assessment, short guided sessions, and an at-home plan you can follow. Each part is safety-minded and personalized to your needs.</p>
        <div class="grid">
          <div class="card">
            <h3>Assess</h3>
            <p>We listen to context — patterns of stress, sleep, or focus — and co-design a small set of practices you can repeat.</p>
          </div>
          <div class="card">
            <h3>Experience</h3>
            <p>Short, guided aromatic moments (in-session or digital) to try scent choices and support regulation. Non-medical and supportive.</p>
          </div>
          <div class="card">
            <h3>Plan</h3>
            <p>A clear, printable session plan and simple blend card you can keep by your bedside or workspace.</p>
          </div>
        </div>
      </div>
    </section>

    <!-- OFFERS (third) -->
    <section class="offers" id="offers">
      <div class="wrap">
        <h2>Offerings</h2>
        <p class="lede">Focused engagements to meet a specific need, from single intensives to short series. All sessions center safety and do not replace medical care.</p>
        <div class="tile-row">
          <div class="tile">
            <h3>Solo Intensive</h3>
            <p>One 60-minute session for a concentrated plan and a blend card to try at home.</p>
            <p class="price">From $95</p>
            <a class="btn" href="/book.html">Book a Solo Intensive</a>
          </div>
          <div class="tile">
            <h3>Three-Visit Path</h3>
            <p>Three sessions over 6 weeks — assess, practice, and integrate a sustainable set of scent routines.</p>
            <p class="price">From $265</p>
            <a class="btn" href="/pricing.html">View Plans</a>
          </div>
          <div class="tile">
            <h3>Custom Blend & Guidance</h3>
            <p>Comes with a labeled glass roll-on or vial and a printable dilution and use guide.</p>
            <p class="price">From $45</p>
            <a class="btn" href="/blends.html">Create a Blend</a>
          </div>
        </div>
      </div>
    </section>

    <!-- SESSION PLANNER (interactive) -->
    <section class="session-planner" id="planner">
      <div class="wrap">
        <h2>Session Planner</h2>
        <p class="lede">Build a short, tailored session plan. Export a simple plaintext plan you can save or message to yourself.</p>
        <form id="planner-form">
          <label>Goal (e.g., focus, wind-down, reset):
            <input type="text" id="goal" placeholder="Enter your immediate intention" required />
          </label>
          <label>Preferred length:
            <select id="length">
              <option value="5">5 minutes</option>
              <option value="10" selected>10 minutes</option>
              <option value="20">20 minutes</option>
            </select>
          </label>
          <label>Format:
            <select id="format">
              <option value="diffuse">Diffuse (room)</option>
              <option value="inhaler">Personal inhaler</option>
              <option value="topical">Topical support (roll-on)</option>
            </select>
          </label>
          <label>Preferred vibe:
            <select id="vibe">
              <option value="calm">Calm</option>
              <option value="focus">Focus</option>
              <option value="uplift">Uplift</option>
              <option value="sleep">Sleep</option>
            </select>
          </label>
          <div class="form-actions">
            <button type="button" class="btn primary" id="build-plan">Build Plan</button>
            <button type="reset" class="btn ghost">Reset</button>
          </div>
        </form>

        <div class="planner-output">
          <textarea id="plan-output" readonly placeholder="Your plan will appear here..."></textarea>
          <div class="output-actions">
            <button id="copy-plan" class="btn">Copy</button>
            <a id="download-plan" class="btn ghost" href="#" download="session-plan.txt">Download</a>
          </div>
        </div>
        <p class="note">Note: This planner is a supportive organizational tool and not medical advice. Patch test guidance and dilution basics are included elsewhere on the site.</p>
      </div>
    </section>

    <!-- STORY (later) -->
    <section class="story" id="story">
      <div class="wrap">
        <h2>Philosophy</h2>
        <p class="lede">The work is quiet and practical: choose a handful of botanical allies, learn how to use them safely, and build short rituals that fit everyday life. Practices may support relaxation, attention, and easier transitions between busy moments.</p>
        <blockquote>"Small, repeatable acts often change how a day feels."</blockquote>
      </div>
    </section>

    <!-- PRICING (later) -->
    <section class="pricing" id="pricing">
      <div class="wrap">
        <h2>Simple pricing</h2>
        <p class="lede">Transparent offerings with clear next steps. Packages are framed around outcomes, not hours.</p>
        <div class="pricing-grid">
          <div class="price-card">
            <h3>Starter</h3>
            <p class="price">$45</p>
            <p>Create a single blend and receive a basic 1-page plan.</p>
            <a class="btn" href="/blends.html">Start a blend</a>
          </div>
          <div class="price-card" aria-current="true">
            <h3>Focused Path</h3>
            <p class="price">$265</p>
            <p>Three short sessions + home plan + two mini blends.</p>
            <a class="btn primary" href="/pricing.html">Choose Focused Path</a>
          </div>
          <div class="price-card">
            <h3>Careful Craft</h3>
            <p class="price">$95</p>
            <p>An in-depth single session for a clear, safe protocol and blend.</p>
            <a class="btn" href="/book.html">Book Careful Craft</a>
          </div>
        </div>
      </div>
    </section>

    <!-- TESTIMONIALS -->
    <section class="testimonials" id="testimonials">
      <div class="wrap">
        <h2>What people notice</h2>
        <div class="test-grid">
          <figure>
            <blockquote>"A small ritual that actually fits my mornings. I feel steadier."</blockquote>
            <figcaption>— A local client</figcaption>
          </figure>
          <figure>
            <blockquote>"Clear instructions, gentle blends, and no fuss."</blockquote>
            <figcaption>— Workshop attendee</figcaption>
          </figure>
        </div>
      </div>
    </section>

    <!-- CTA -->
    <section class="cta" id="cta">
      <div class="wrap">
        <h2>Ready for a guided, safety-forward approach?</h2>
        <p>Book a discovery chat and we'll co-create a concise plan you can try at home.</p>
        <p><a class="btn primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a> <a class="btn" href="/contact.html">Ask a question</a></p>
      </div>
    </section>
  </main>

  <footer class="site-footer">
    <div class="wrap">
      <div class="foot-grid">
        <div>
          <strong>{{BUSINESS_NAME}}</strong>
          <p>{{CITY}}, {{STATE}}</p>
        </div>
        <div>
          <nav>
            <a href="/services.html">Offerings</a>
            <a href="/blends.html">Blends</a>
            <a href="/shop.html">Shop</a>
            <a href="/contact.html">Contact</a>
          </nav>
        </div>
        <div>
          <p>Call: <a href="tel:{{PHONE}}">{{PHONE}}</a></p>
          <p>Email: <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></p>
        </div>
      </div>
      <p class="fineprint">All aromatherapy suggestions are non-medical and safety-forward. Refer to the FAQ for dilution, patch testing, pregnancy, and pet considerations.</p>
    </div>
  </footer>

  <script src="assets/js/main.js" defer></script>
</body>
</html>"} 
